long power(long a, long b, long mod) {
    long result = 1;
    a %= mod;
    while (b > 0) {
        if ((b & 1) == 1) result = result * a % mod;   // current bit is 1
        a = a * a % mod;                                 // square the base
        b >>= 1;                                         // move to the next bit
    }
    return result;
}

