function power(a, b, mod) {
  a = BigInt(a); b = BigInt(b); mod = BigInt(mod);   // BigInt avoids precision loss
  let result = 1n;
  a %= mod;
  while (b > 0n) {
    if (b & 1n) result = (result * a) % mod;   // current bit is 1
    a = (a * a) % mod;                          // square the base
    b >>= 1n;                                   // move to the next bit
  }
  return result;
}
